import { Router } from "express";
import { authMiddleware } from "../middlewares/auth.middleware.js";
import * as projectControllers from "../controllers/project.controller.js";
const router = Router();
router.post("/", authMiddleware, projectControllers.createProject);
router.get("/", authMiddleware, projectControllers.getProjects);
router.post("/:id/members", authMiddleware, projectControllers.addMember);
router.get("/:id/members", authMiddleware, projectControllers.getMembers);
router.delete("/:id/members/:userId", authMiddleware, projectControllers.removeMember);
export default router;
